    let response = await evaluatePermission(collaboratorSession?.token ?? "", repo.id, "read");
    console.log(`[probe] collaborator GET /repos/${repo.id}/read -> ${response.status} (expected 200)`);
    expect(response.status).toBe(200);

    // Revoke the collaborator's access
    response = await deleteCollaborator(ownerSession?.token ?? "", repo.id, collaborator.username);
    console.log(`[probe] owner DELETE /repos/${repo.id}/collaborators/${collaborator.username} -> ${response.status} (expected 204)`);
    expect(response.status).toBe(204);

    // Collaborator should no longer be able to read the repo
    response = await evaluatePermission(collaboratorSession?.token ?? "", repo.id, "read");
    console.log(`[probe] collaborator GET /repos/${repo.id}/read -> ${response.status} (expected 404)`);
    if (response.status === 404 && response.headers.get("content-type") === "text/plain" && (await response.text()) === "404 Not Found") {
      throw new Error("probe not applicable: precondition absent");
    }
    expect(response.status).toBe(404);
  });
});
